func (c *Client) WithdrawProjectGrant(tenant_id string, environment_id string, organization_id string, grant_id string, query url.Values) (*http.Response, error) {
	return c.do("DELETE", "/v1/tenants/" + escape(tenant_id) + "/environments/" + escape(environment_id) + "/organizations/" + escape(organization_id) + "/project-grants/" + escape(grant_id), query, nil)
}
